/**
 * Provider logos, served from public/logos/<slug>.webp (64x64, regenerated by `bun run logos`
 * from the sources listed in scripts/logos.ts). A provider without one, such as Truphone (now
 * 1GLOBAL) or a new provider added by an import, gets its initials instead.
 */
export const LOGOS: ReadonlySet<string> = new Set([
  "4sesim",
  "airalo",
  "alosim",
  "esimx",
  "flexiroam",
  "gigsky",
  "holafly",
  "instabridge",
  "jambosim",
  "jetpac",
  "mayamobile",
  "nomad",
  "roamic",
  "saily",
  "ubigi",
  "yatelo",
  "yesim",
]);

/** "Maya Mobile" → "mayamobile", "4S eSIM" → "4sesim". */
export const providerSlug = (name: string) =>
  name
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]/g, "");

export function providerLogo(name: string): string | null {
  const slug = providerSlug(name);
  return LOGOS.has(slug) ? `/logos/${slug}.webp` : null;
}

/** First letter of the first two words: "Maya Mobile" → "MM", "Truphone" → "T". */
export const providerInitials = (name: string) =>
  name
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((w) => w[0]?.toUpperCase() ?? "")
    .join("");
